import{_ as t,o as d,c as o,a3 as r}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Configuration de Calendar Card Pro","description":"Référence de configuration pour Calendar Card Pro.","frontmatter":{"title":"Configuration de Calendar Card Pro","description":"Référence de configuration pour Calendar Card Pro."},"headers":[],"relativePath":"fr/collection/calendar-card-pro/konfiguration.md","filePath":"fr/collection/calendar-card-pro/konfiguration.md","lastUpdated":1793447386000}'),c={name:"fr/collection/calendar-card-pro/konfiguration.md"};function a(n,e,i,l,s,u){return d(),o("div",null,[...e[0]||(e[0]=[r('<p><a id="calendar-card-pro-configuration"></a><a id="orientation-actuelle"></a></p><h1 id="konfigurationsreferenz" tabindex="-1">Référence de configuration <a class="header-anchor" href="#konfigurationsreferenz" aria-label="Permalink to &quot;Référence de configuration {#konfigurationsreferenz}&quot;">​</a></h1><p>Cette page reprend les groupes d&#39;options de la documentation de référence originale. Pour des exemples détaillés, la documentation originale en anglais fait foi.</p><h2 id="neu-in-v4-1-0" tabindex="-1">Nouveautés dans la version 1.0 <a class="header-anchor" href="#neu-in-v4-1-0" aria-label="Permalink to &quot;Nouveautés dans la version 1.0 {#neu-in-v4-1-0}&quot;">​</a></h2><p>La version <code>4.1.0</code> ajoute plusieurs contrôles liés au calendrier :</p><ul><li><code>event_type</code> permet de distinguer les événements avec heure précise des événements sur toute la journée. - <code>filter_field</code> permet à <code>blocklist</code> et <code>allowlist</code> d&#39;agir sur le titre, le lieu ou la description.</li><li><code>replace_field</code>, <code>replace_pattern</code> et <code>replace_with</code> modifient le texte affiché, sans pour autant altérer l&#39;événement du calendrier lui-même.</li><li><code>allday_expires_at</code> permet de faire se terminer plus tôt dans la journée les événements d&#39;une journée entière.</li><li><code>days_of_week</code> limite un calendrier aux jours ouvrables ou au week-end.</li><li><code>allday_badge</code>, <code>allday_badge_style</code> et <code>allday_badge_color</code> gèrent le nouvel affichage sous forme de badge pour les événements d&#39;une journée entière.</li></ul><h2 id="grundeinstellungen" tabindex="-1">Paramètres de base <a class="header-anchor" href="#grundeinstellungen" aria-label="Permalink to &quot;Paramètres de base {#grundeinstellungen}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Par défaut</th><th>Description</th></tr></thead><tbody><tr><td><code>entities</code></td><td>array</td><td>Obligatoire</td><td>Liste des entités de calendrier, avec possibilité de définir des paramètres spécifiques pour chaque calendrier.</td></tr><tr><td><code>view</code></td><td>string</td><td><code>list</code></td><td>Mise en page : <code>list</code> pour afficher les jours les uns en dessous des autres, <code>column</code> pour les afficher côte à côte.</td></tr><tr><td><code>start_date</code></td><td>string</td><td>aujourd&#39;hui</td><td>Date de début, sous forme de <code>YYYY-MM-DD</code> ou d&#39;expression relative telle que <code>today+7</code>, <code>start_of_week</code>, <code>monday+1w</code>.</td></tr><tr><td><code>days_to_show</code></td><td>number</td><td><code>3</code></td><td>Nombre de jours affichés.</td></tr><tr><td><code>event_type</code></td><td>string</td><td><code>all</code></td><td>Type d&#39;événement : <code>all</code>, <code>timed</code> ou <code>all_day</code>. Peut être défini globalement ou par calendrier.</td></tr><tr><td><code>compact_days_to_show</code></td><td>number</td><td>-</td><td>Nombre de jours en mode compact.</td></tr><tr><td><code>compact_events_to_show</code></td><td>number</td><td>-</td><td>Nombre d&#39;événements en mode compact.</td></tr><tr><td><code>compact_events_complete_days</code></td><td>boolean</td><td><code>false</code></td><td>Affiche tous les événements pour les jours où au moins un événement est visible.</td></tr><tr><td><code>show_empty_days</code></td><td>boolean</td><td><code>false</code></td><td>Affiche les jours sans événement. Dans la vue en colonnes, la valeur par défaut est <code>true</code>.</td></tr><tr><td><code>hide_when_empty</code></td><td>boolean</td><td><code>false</code></td><td>Masquer la carte s&#39;il n&#39;y a aucun événement à venir.</td></tr><tr><td><code>empty_day_text</code></td><td>string</td><td>valeur par défaut traduite</td><td>Texte personnalisé pour les jours sans événement ou les cartes entièrement vides.</td></tr><tr><td><code>filter_duplicates</code></td><td>boolean</td><td><code>false</code></td><td>Masquer les événements en double si le titre, le début, la fin et le lieu sont identiques.</td></tr><tr><td><code>split_multiday_events</code></td><td>boolean</td><td><code>false</code></td><td>Afficher les événements sur plusieurs jours pour chaque jour concerné. Dans la vue en colonnes, la valeur par défaut est <code>true</code>.</td></tr><tr><td><code>language</code></td><td>string</td><td>Système, repli sur <code>en</code></td><td>Langue des textes de la carte, détectée automatiquement depuis Home Assistant.</td></tr><tr><td><code>column</code></td><td>object</td><td>hérite des valeurs de niveau supérieur</td><td>Options d&#39;affichage spécifiques pour <code>view: column</code>.</td></tr></tbody></table><h2 id="nur-fur-die-spaltenansicht" tabindex="-1">Uniquement pour la vue en colonnes <a class="header-anchor" href="#nur-fur-die-spaltenansicht" aria-label="Permalink to &quot;Uniquement pour la vue en colonnes {#nur-fur-die-spaltenansicht}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Valeur par défaut</th><th>Description</th></tr></thead><tbody><tr><td><code>column.day_header_gap</code></td><td>string</td><td><code>8px</code></td><td>Espacement entre l&#39;en-tête du jour et le premier événement.</td></tr><tr><td><code>column.day_header_separator_width</code></td><td>string</td><td><code>0px</code></td><td>Épaisseur de la ligne sous l&#39;en-tête du jour.</td></tr><tr><td><code>column.day_header_separator_color</code></td><td>string</td><td><code>var(--divider-color)</code></td><td>Couleur de la ligne sous l&#39;en-tête du jour.</td></tr><tr><td><code>column.min_day_width</code></td><td>number</td><td><code>140</code></td><td>Largeur minimale des colonnes en pixels.</td></tr><tr><td><code>column.min_days_to_show</code></td><td>number</td><td><code>days_to_show</code></td><td>Nombre minimal de colonnes visibles.</td></tr><tr><td><code>column.min_days_fallback</code></td><td>string</td><td><code>list</code></td><td>Comportement en cas d&#39;espace insuffisant : <code>list</code> ou <code>cramp</code>.</td></tr></tbody></table><h2 id="optionen-ohne-wirkung-in-der-spaltenansicht" tabindex="-1">Options sans effet dans la vue en colonnes <a class="header-anchor" href="#optionen-ohne-wirkung-in-der-spaltenansicht" aria-label="Permalink to &quot;Options sans effet dans la vue en colonnes {#optionen-ohne-wirkung-in-der-spaltenansicht}&quot;">​</a></h2><p>Ces options restent pertinentes pour la vue en liste, mais n&#39;ont pas d&#39;effet direct dans la vue en colonnes :</p><p><code>date_vertical_alignment</code>, <code>today_indicator_position</code>, <code>compact_events_to_show</code>, <code>compact_days_to_show</code>, <code>compact_events_complete_days</code>, ainsi que <code>split_multiday_events</code> (lié au calendrier).</p><h2 id="kalenderbezogene-optionen" tabindex="-1">Options liées au calendrier <a class="header-anchor" href="#kalenderbezogene-optionen" aria-label="Permalink to &quot;Options liées au calendrier {#kalenderbezogene-optionen}&quot;">​</a></h2><p>Une entrée dans <code>entities</code> peut être soit un identifiant d&#39;entité (Entity ID), soit un objet doté de ses propres paramètres.</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>entity</code></td><td>Entité de calendrier, par exemple <code>calendar.family</code>.</td></tr><tr><td><code>label</code></td><td>Libellé personnalisé du calendrier.</td></tr><tr><td><code>label_type</code></td><td>Détermine la manière dont le libellé est lu.</td></tr><tr><td><code>color</code></td><td>Couleur du calendrier.</td></tr><tr><td><code>accent_color</code></td><td>Couleur d&#39;accentuation pour la ligne et les arrière-plans facultatifs.</td></tr><tr><td><code>label_icon_color</code></td><td>Couleur du libellé/de l&#39;icône.</td></tr><tr><td><code>show_time</code></td><td>Afficher l&#39;heure pour ce calendrier.</td></tr><tr><td><code>show_location</code></td><td>Afficher le lieu pour ce calendrier.</td></tr><tr><td><code>location_icon</code></td><td>Icône pour les informations de lieu de ce calendrier, par exemple <code>mdi:office-building</code> ; peut remplacer la détection automatique de Teams.</td></tr><tr><td><code>show_description</code></td><td>Afficher la description pour ce calendrier.</td></tr><tr><td><code>compact_events_to_show</code></td><td>Limite compacte pour ce calendrier.</td></tr><tr><td><code>blocklist</code></td><td>Exclure des termes ou des modèles.</td></tr><tr><td><code>allowlist</code></td><td>Afficher uniquement les termes ou modèles correspondants.</td></tr><tr><td><code>filter_field</code></td><td>Champ pour <code>blocklist</code>/<code>allowlist</code> : <code>title</code>, <code>location</code> ou <code>description</code>.</td></tr><tr><td><code>replace_field</code></td><td>Champ pour le remplacement de texte : <code>title</code>, <code>location</code> ou <code>description</code>.</td></tr><tr><td><code>replace_pattern</code></td><td>Modèle d&#39;expression régulière (regex) à remplacer ou à supprimer dans le champ sélectionné.</td></tr><tr><td><code>replace_with</code></td><td>Texte de remplacement ; en l&#39;absence de <code>replace_pattern</code>, le champ entier est remplacé.</td></tr><tr><td><code>split_multiday_events</code></td><td>Scinder les événements s&#39;étendant sur plusieurs jours pour ce calendrier.</td></tr><tr><td><code>event_type</code></td><td>Type d&#39;événement lié au calendrier : <code>all</code>, <code>timed</code> ou <code>all_day</code>.</td></tr><tr><td><code>allday_expires_at</code></td><td>Heure (au format <code>HH:MM</code>) à partir de laquelle les événements sur toute la journée de ce calendrier sont considérés comme passés.</td></tr><tr><td><code>days_of_week</code></td><td>Limitation à <code>weekdays</code> ou <code>weekends</code>.</td></tr></tbody></table><h2 id="header" tabindex="-1">En-tête <a class="header-anchor" href="#header" aria-label="Permalink to &quot;En-tête {#header}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Par défaut</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td>chaîne</td><td>-</td><td>Titre de la carte ; peut contenir des modèles (templates) Home Assistant.</td></tr><tr><td><code>title_font_size</code></td><td>chaîne</td><td><code>--calendar-card-font-size-title</code></td><td>Taille de la police du titre.</td></tr><tr><td><code>title_color</code></td><td>chaîne</td><td><code>--calendar-card-color-title</code></td><td>Couleur du titre.</td></tr></tbody></table><h2 id="layout-und-abstande" tabindex="-1">Mise en page et espacements <a class="header-anchor" href="#layout-und-abstande" aria-label="Permalink to &quot;Mise en page et espacements {#layout-und-abstande}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Par défaut</th><th>Description</th></tr></thead><tbody><tr><td><code>background_color</code></td><td>chaîne</td><td><code>--ha-card-background</code></td><td>Couleur d&#39;arrière-plan de la carte.</td></tr><tr><td><code>accent_color</code></td><td>chaîne</td><td><code>#03a9f4</code></td><td>Couleur d&#39;accentuation de la ligne verticale et des badges optionnels (rendez-vous / journée entière).</td></tr><tr><td><code>vertical_line_width</code></td><td>string</td><td><code>2px</code></td><td>Épaisseur de la ligne verticale.</td></tr><tr><td><code>day_spacing</code></td><td>string</td><td><code>10px</code></td><td>Espacement entre les jours ou les colonnes.</td></tr><tr><td><code>event_spacing</code></td><td>string</td><td><code>4px</code></td><td>Espacement interne au sein d&#39;un rendez-vous.</td></tr><tr><td><code>additional_card_spacing</code></td><td>string</td><td><code>0px</code></td><td>Espacement supplémentaire en haut et en bas de la carte.</td></tr><tr><td><code>height</code></td><td>string</td><td><code>auto</code></td><td>Hauteur fixe et précise de la carte.</td></tr><tr><td><code>max_height</code></td><td>string</td><td><code>none</code></td><td>Hauteur maximale de la carte en cas d&#39;augmentation du contenu.</td></tr></tbody></table><h2 id="wochennummern-und-trennlinien" tabindex="-1">Numéros de semaine et lignes de séparation <a class="header-anchor" href="#wochennummern-und-trennlinien" aria-label="Permalink to &quot;Numéros de semaine et lignes de séparation {#wochennummern-und-trennlinien}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Valeur par défaut</th><th>Description</th></tr></thead><tbody><tr><td><code>show_week_numbers</code></td><td>chaîne</td><td><code>null</code></td><td>Affichage des numéros de semaine : <code>iso</code>, <code>simple</code> ou désactivé.</td></tr><tr><td><code>show_current_week_number</code></td><td>booléen</td><td><code>true</code></td><td>Affichage du numéro de semaine pour la semaine en cours ou la première semaine.</td></tr><tr><td><code>week_number_font_size</code></td><td>chaîne</td><td><code>12px</code></td><td>Taille de police du numéro de semaine.</td></tr><tr><td><code>week_number_color</code></td><td>chaîne</td><td><code>var(--primary-text-color)</code></td><td>Couleur du texte du numéro de semaine.</td></tr><tr><td><code>week_number_background_color</code></td><td>chaîne</td><td><code>#03a9f450</code></td><td>Couleur d&#39;arrière-plan du numéro de semaine.</td></tr><tr><td><code>first_day_of_week</code></td><td>chaîne</td><td><code>system</code></td><td>Début de la semaine : <code>monday</code>, <code>sunday</code> ou <code>system</code>.</td></tr><tr><td><code>day_separator_width</code></td><td>chaîne</td><td><code>0px</code></td><td>Ligne de séparation entre les jours.</td></tr><tr><td><code>day_separator_color</code></td><td>chaîne</td><td><code>var(--secondary-text-color)</code></td><td>Couleur de la ligne de séparation entre les jours.</td></tr><tr><td><code>week_separator_width</code></td><td>chaîne</td><td><code>0px</code></td><td>Ligne de séparation entre les semaines.</td></tr><tr><td><code>week_separator_color</code></td><td>chaîne</td><td><code>#03a9f450</code></td><td>Couleur de la ligne de séparation entre les semaines.</td></tr><tr><td><code>month_separator_width</code></td><td>chaîne</td><td><code>0px</code></td><td>Ligne de séparation entre les mois.</td></tr><tr><td><code>month_separator_color</code></td><td>chaîne</td><td><code>var(--primary-text-color)</code></td><td>Couleur de la ligne de séparation des mois.</td></tr></tbody></table><h2 id="heute-markierung" tabindex="-1">Indicateur « Aujourd&#39;hui » <a class="header-anchor" href="#heute-markierung" aria-label="Permalink to &quot;Indicateur « Aujourd&#39;hui » {#heute-markierung}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Valeur par défaut</th><th>Description</th></tr></thead><tbody><tr><td><code>today_indicator</code></td><td>booléen/chaîne</td><td><code>false</code></td><td>Indicateur « Aujourd&#39;hui » : <code>true</code>, <code>dot</code>, <code>pulse</code>, <code>glow</code>, icône MDI, émoji ou chemin d&#39;accès à une image.</td></tr><tr><td><code>today_indicator_position</code></td><td>chaîne</td><td><code>15% 50%</code></td><td>Position au format CSS.</td></tr><tr><td><code>today_indicator_color</code></td><td>chaîne</td><td><code>#03a9f4</code></td><td>Couleur de l&#39;indicateur.</td></tr><tr><td><code>today_indicator_size</code></td><td>chaîne</td><td><code>6px</code></td><td>Taille de l&#39;indicateur.</td></tr></tbody></table><h2 id="datumsspalte" tabindex="-1">Colonne des dates <a class="header-anchor" href="#datumsspalte" aria-label="Permalink to &quot;Colonne des dates {#datumsspalte}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Valeur par défaut</th><th>Description</th></tr></thead><tbody><tr><td><code>date_vertical_alignment</code></td><td>chaîne</td><td><code>middle</code></td><td>Alignement vertical : <code>top</code>, <code>middle</code>, <code>bottom</code>.</td></tr><tr><td><code>weekday_font_size</code></td><td>chaîne</td><td><code>14px</code></td><td>Taille de police du jour de la semaine.</td></tr><tr><td><code>weekday_color</code></td><td>chaîne</td><td><code>--primary-text-color</code></td><td>Couleur du jour de la semaine.</td></tr><tr><td><code>day_font_size</code></td><td>chaîne</td><td><code>26px</code></td><td>Taille de police du numéro du jour.</td></tr><tr><td><code>day_color</code></td><td>chaîne</td><td><code>--primary-text-color</code></td><td>Couleur du numéro du jour.</td></tr><tr><td><code>show_month</code></td><td>booléen</td><td><code>true</code></td><td>Affichage des noms des mois.</td></tr><tr><td><code>month_font_size</code></td><td>chaîne</td><td><code>12px</code></td><td>Taille de police du mois.</td></tr><tr><td><code>month_color</code></td><td>chaîne</td><td><code>--primary-text-color</code></td><td>Couleur du mois.</td></tr><tr><td><code>weekend_weekday_color</code></td><td>chaîne</td><td>hérite de <code>weekday_color</code></td><td>Couleur du jour de la semaine pendant les week-ends.</td></tr><tr><td><code>weekend_day_color</code></td><td>chaîne</td><td>hérite de <code>day_color</code></td><td>Couleur du numéro du jour pendant les week-ends.</td></tr><tr><td><code>weekend_month_color</code></td><td>chaîne</td><td>hérite de <code>month_color</code></td><td>Couleur du mois pendant les week-ends.</td></tr><tr><td><code>today_weekday_color</code></td><td>chaîne</td><td>hérite de week-end/par défaut</td><td>Couleur du jour de la semaine pour aujourd&#39;hui.</td></tr><tr><td><code>today_day_color</code></td><td>chaîne</td><td>hérite de week-end/par défaut</td><td>Couleur du numéro du jour pour aujourd&#39;hui.</td></tr><tr><td><code>today_month_color</code></td><td>chaîne</td><td>hérite de week-end/par défaut</td><td>Couleur du mois pour aujourd&#39;hui.</td></tr></tbody></table><h2 id="terminspalte" tabindex="-1">Colonne des rendez-vous <a class="header-anchor" href="#terminspalte" aria-label="Permalink to &quot;Colonne des rendez-vous {#terminspalte}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Valeur par défaut</th><th>Description</th></tr></thead><tbody><tr><td><code>event_background_opacity</code></td><td>nombre</td><td><code>0</code></td><td>Opacité de l&#39;arrière-plan pour les rendez-vous avec une couleur d&#39;accentuation, de 0 à 100.</td></tr><tr><td><code>event_icon_vertical_alignment</code></td><td>string</td><td><code>top</code></td><td>Alignement vertical de l&#39;icône : <code>top</code>, <code>middle</code>, <code>bottom</code>.</td></tr><tr><td><code>show_past_events</code></td><td>boolean</td><td><code>false</code></td><td>Afficher les rendez-vous déjà terminés.</td></tr><tr><td><code>show_countdown</code></td><td>boolean</td><td><code>false</code></td><td>Afficher le compte à rebours jusqu&#39;au rendez-vous.</td></tr><tr><td><code>show_countdown_allday</code></td><td>boolean</td><td><code>true</code></td><td>Afficher le compte à rebours également pour les rendez-vous sur toute la journée.</td></tr><tr><td><code>show_multiday_allday_time</code></td><td>boolean</td><td><code>true</code></td><td>Afficher une ligne temporelle pour les rendez-vous sur toute la journée s&#39;étendant sur plusieurs jours ; elle indique la date de fin.</td></tr><tr><td><code>allday_badge</code></td><td>string</td><td><code>off</code></td><td>Position du badge « toute la journée » : <code>off</code>, <code>title</code> ou <code>time</code>.</td></tr><tr><td><code>allday_badge_style</code></td><td>string</td><td><code>subtle</code></td><td>Style du badge : <code>subtle</code>, <code>outline</code>, <code>tinted</code> ou <code>filled</code>.</td></tr><tr><td><code>allday_badge_color</code></td><td>string</td><td><code>accent</code></td><td>Couleur du badge : <code>accent</code>, <code>text</code> ou une couleur CSS.</td></tr><tr><td><code>show_progress_bar</code></td><td>booléen</td><td><code>false</code></td><td>Afficher la barre de progression pour les rendez-vous en cours.</td></tr><tr><td><code>progress_bar_color</code></td><td>chaîne</td><td><code>var(--secondary-text-color)</code></td><td>Couleur de la barre de progression.</td></tr><tr><td><code>progress_bar_height</code></td><td>chaîne</td><td>calculée</td><td>Hauteur de la barre de progression.</td></tr><tr><td><code>progress_bar_width</code></td><td>chaîne</td><td>selon la mise en page</td><td>Largeur de la barre de progression.</td></tr><tr><td><code>empty_day_color</code></td><td>chaîne</td><td><code>--primary-text-color</code></td><td>Couleur du texte pour les jours vides.</td></tr><tr><td><code>event_font_size</code></td><td>chaîne</td><td><code>14px</code></td><td>Taille de la police du titre du rendez-vous.</td></tr><tr><td><code>title_max_lines</code></td><td>nombre</td><td><code>0</code></td><td>Nombre maximal de lignes pour le titre du rendez-vous ; <code>0</code> = illimité.</td></tr><tr><td><code>event_color</code></td><td>chaîne</td><td><code>--primary-text-color</code></td><td>Couleur du titre du rendez-vous.</td></tr><tr><td><code>show_time</code></td><td>booléen</td><td><code>true</code></td><td>Afficher l&#39;heure du rendez-vous.</td></tr><tr><td><code>show_single_allday_time</code></td><td>boolean</td><td><code>true</code></td><td>Afficher l&#39;heure pour les événements individuels sur toute la journée.</td></tr><tr><td><code>time_24h</code></td><td>boolean</td><td>Système</td><td>Utiliser le format 24 heures.</td></tr><tr><td><code>time_two_digit_hours</code></td><td>boolean</td><td><code>false</code></td><td>Afficher les heures sur deux chiffres.</td></tr><tr><td><code>show_end_time</code></td><td>boolean</td><td><code>true</code></td><td>Afficher l&#39;heure de fin.</td></tr><tr><td><code>time_icon_size</code></td><td>string</td><td><code>14px</code></td><td>Taille de l&#39;icône d&#39;horloge.</td></tr><tr><td><code>time_font_size</code></td><td>string</td><td><code>12px</code></td><td>Taille de la police de l&#39;heure.</td></tr><tr><td><code>time_color</code></td><td>string</td><td><code>--secondary-text-color</code></td><td>Couleur de l&#39;heure.</td></tr><tr><td><code>time_max_lines</code></td><td>number</td><td><code>0</code></td><td>Nombre maximal de lignes pour le texte de l&#39;heure.</td></tr><tr><td><code>show_location</code></td><td>boolean</td><td><code>true</code></td><td>Afficher le lieu.</td></tr><tr><td><code>show_location_allday</code></td><td>boolean</td><td><code>true</code></td><td>Afficher le lieu même pour les événements sur toute la journée, si <code>show_location</code> est activé.</td></tr><tr><td><code>remove_location_country</code></td><td>boolean/string</td><td><code>false</code></td><td>Supprimer les noms de pays des lieux, éventuellement via une expression régulière (regex).</td></tr><tr><td><code>location_icon_size</code></td><td>string</td><td><code>14px</code></td><td>Taille de l&#39;icône du lieu.</td></tr><tr><td><code>location_font_size</code></td><td>string</td><td><code>12px</code></td><td>Taille de la police du lieu.</td></tr><tr><td><code>location_color</code></td><td>string</td><td><code>--secondary-text-color</code></td><td>Couleur du lieu.</td></tr><tr><td><code>location_max_lines</code></td><td>number</td><td><code>0</code></td><td>Nombre maximal de lignes pour le lieu.</td></tr><tr><td><code>show_description</code></td><td>boolean</td><td><code>false</code></td><td>Afficher la description.</td></tr><tr><td><code>show_description_allday</code></td><td>boolean</td><td><code>true</code></td><td>Afficher les descriptions même pour les événements sur toute la journée, si <code>show_description</code> est activé.</td></tr><tr><td><code>description_icon_size</code></td><td>string</td><td><code>14px</code></td><td>Taille de l&#39;icône de description.</td></tr><tr><td><code>description_font_size</code></td><td>string</td><td><code>12px</code></td><td>Taille de la police de la description.</td></tr><tr><td><code>description_color</code></td><td>string</td><td><code>--secondary-text-color</code></td><td>Couleur de la description.</td></tr><tr><td><code>description_max_lines</code></td><td>number</td><td><code>0</code></td><td>Nombre maximal de lignes pour la description.</td></tr></tbody></table><h2 id="wetter" tabindex="-1">Météo <a class="header-anchor" href="#wetter" aria-label="Permalink to &quot;Météo {#wetter}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Par défaut</th><th>Description</th></tr></thead><tbody><tr><td><code>weather</code></td><td>object</td><td>-</td><td>Configuration météo.</td></tr><tr><td><code>weather.entity</code></td><td>string</td><td>-</td><td>Entité météo pour les prévisions.</td></tr><tr><td><code>weather.position</code></td><td>string</td><td><code>date</code></td><td>Position : <code>none</code>, <code>date</code>, <code>event</code>, <code>both</code>.</td></tr><tr><td><code>weather.date</code></td><td>object</td><td>-</td><td>Affichage de la météo dans l&#39;en-tête journalier.</td></tr><tr><td><code>weather.event</code></td><td>object</td><td>-</td><td>Affichage de la météo à côté des rendez-vous.</td></tr></tbody></table><p><code>weather.date</code> accepte : <code>show_conditions</code>, <code>show_high_temp</code>, <code>show_low_temp</code>, <code>show_uv_index</code>, <code>uv_index_threshold</code>, <code>icon_size</code>, <code>font_size</code>, <code>color</code>.</p><p><code>weather.event</code> accepte : <code>show_conditions</code>, <code>show_temp</code>, <code>show_uv_index</code>, <code>uv_index_threshold</code>, <code>daily_forecast_fallback</code>, <code>max_lines</code>, <code>icon_size</code>, <code>font_size</code>, <code>color</code>.</p><h2 id="aktionen" tabindex="-1">Actions <a class="header-anchor" href="#aktionen" aria-label="Permalink to &quot;Actions {#aktionen}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Par défaut</th><th>Description</th></tr></thead><tbody><tr><td><code>tap_action</code></td><td>object</td><td><code>none</code></td><td>Action lors d&#39;un appui sur la carte.</td></tr><tr><td><code>hold_action</code></td><td>object</td><td><code>none</code></td><td>Action lors d&#39;un appui prolongé sur la carte.</td></tr></tbody></table><p>Les paramètres d&#39;action peuvent être, selon l&#39;action :</p><p><code>action</code>, <code>navigation_path</code>, <code>service</code>, <code>service_data</code>, <code>url_path</code>, <code>open_tab</code>.</p><h2 id="cache-und-aktualisierung" tabindex="-1">Cache et mise à jour <a class="header-anchor" href="#cache-und-aktualisierung" aria-label="Permalink to &quot;Cache et mise à jour {#cache-und-aktualisierung}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Par défaut</th><th>Description</th></tr></thead><tbody><tr><td><code>refresh_interval</code></td><td>number</td><td><code>30</code></td><td>Minutes entre les mises à jour des données.</td></tr><tr><td><code>refresh_on_navigate</code></td><td>boolean</td><td><code>true</code></td><td>Recharger lors du passage d&#39;une vue du tableau de bord à une autre.</td></tr></tbody></table>',38)])])}const m=t(c,[["render",a]]);export{p as __pageData,m as default};
